#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../bitonic-sort-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int exponent=14,n=1<<exponent,repeat=argc>1?atoi(argv[1]):3;std::vector<int>input(n),expected,got(n);srand(123);for(int i=0;i<n;i++)input[i]=rand()%1000;expected=input;std::sort(expected.begin(),expected.end());int*data;CK(cudaMalloc(&data,n*4));CK(cudaMemcpy(data,input.data(),n*4,cudaMemcpyHostToDevice));auto sort=[&](){for(int step=0;step<exponent;step++)for(int stage=step;stage>=0;stage--)bitonic_sort<<<n/256,256>>>(1<<(stage+1),1<<(step-stage),data);};sort();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double elapsed=0;for(int rep=0;rep<repeat;rep++){CK(cudaMemcpy(data,input.data(),n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();sort();CK(cudaDeviceSynchronize());elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;}CK(cudaMemcpy(got.data(),data,n*4,cudaMemcpyDeviceToHost));int ma=0;for(int i=0;i<n;i++)ma=std::max(ma,abs(got[i]-expected[i]));bool ok=got==expected;all&=ok;char file[100];sprintf(file,"bitonic_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(got.data(),4,n,f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"complete_14level_105stage_bitonic_sort_reset_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",n,ma,repeat,file,n);}CK(cudaFree(data));puts(all?"PASS":"FAIL");return all?0:1;}
